import{_ as e,o as t,c as r,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const c=JSON.parse('{"title":"鲍勃·德纳姆","description":"","frontmatter":{"title":"鲍勃·德纳姆","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/鲍勃·德纳姆.md","filePath":"04_people/鲍勃·德纳姆.md"}'),o={name:"04_people/鲍勃·德纳姆.md"};function i(n,a,s,h,_,d){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="鲍勃·德纳姆-bob-denham" tabindex="-1">鲍勃·德纳姆（Bob Denham） <a class="header-anchor" href="#鲍勃·德纳姆-bob-denham" aria-label="Permalink to &quot;鲍勃·德纳姆（Bob Denham）&quot;">​</a></h1><ul><li><strong>角色职位</strong>：所罗门兄弟高管</li><li><strong>与巴菲特关系</strong>：巴菲特收购所罗门后任命的公司高管之一</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>鲍勃·德纳姆是所罗门兄弟公司的核心高管，在公司历史上最艰难的时期之一担任重要管理职务。1991年，所罗门兄弟因约翰·梅里韦瑟违规炒作美国国债而爆发丑闻，公司一度濒临破产边缘，被美国财政部威胁吊销国债交易资格。这是华尔街历史上最严重的危机事件之一，整个公司笼罩在不确定的阴影之下。</p><p>巴菲特在此关键时刻亲自介入，不仅投入个人资本，还深度参与公司危机管理。德纳姆作为公司高管团队的重要成员，在配合巴菲特稳定公司局面、完成与监管机构的谈判中发挥了作用。他与其他高管一起，帮助所罗门兄弟度过了这场几乎致命的危机。</p><p>所罗门兄弟在危机后的重建过程中，德纳姆继续担任管理职务，协助公司逐步恢复市场地位。在他和其他管理层的共同努力下，所罗门兄弟最终走出了丑闻的阴影，并最终成为伯克希尔·哈撒韦的全资子公司。德纳姆在公司治理和业务恢复方面所做的贡献，为巴菲特日后对所罗门的完全整合奠定了基础。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1991年</strong>：所罗门兄弟国债丑闻爆发，担任公司高管应对危机</li><li><strong>1992年</strong>：参与公司重组整改，协助巴菲特完成与财政部的和解</li><li><strong>1997年</strong>：所罗门被巴菲特完全收购后，继续参与公司整合</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=鲍勃·德纳姆在1997年股东信中的原话">1997年：完整翻译|/01_letters/1997年/翻译</a></li><li><a href="/search.html?q=鲍勃·德纳姆在1992年股东信中的原话">1992年：完整翻译|/01_letters/1992年/翻译</a></li></ul>',11)])])}const m=e(o,[["render",i]]);export{c as __pageData,m as default};
